// Package legal carries the licences BeziSync ships in its binary: BeziSync's own NOTICE and
// Apache License, then every third-party Go module it links, with their licences and notices.
// licenses.txt is generated by `make licenses` (tools/cmd/licenses); CI fails when it is stale.
package legal

import _ "embed"

// Licenses is the text of licenses.txt, printed by `bezisync licenses` and served at
// /api/v1/system/licenses.
//
//go:embed licenses.txt
var Licenses string
